-- User guide, one article per role or task, in French and English, in the
-- "Guide" category of the knowledge base. Published so every user finds it
-- in the knowledge base and through the IT assistant.
begin;

insert into public.kb_articles (title, title_en, category, published, created_by, updated_by, body, body_en)
select v.title, v.title_en, 'Guide', true, null, null, v.body, v.body_en
from (values
  ('Guide : première connexion et double authentification', 'Guide: first sign-in and two-step verification',
   E'1. Ouvrez https://onomo-ticketing.vercel.app et connectez-vous avec l''adresse e-mail et le mot de passe temporaire reçus de l''IT.\n2. Choisissez un nouveau mot de passe personnel : c''est obligatoire à la première connexion.\n3. Si la double authentification vous est demandée, installez Microsoft Authenticator (ou une autre application d''authentification) sur votre téléphone, scannez le QR code puis saisissez le code à 6 chiffres.\n4. Choisissez votre langue (FR, EN ou AR) en haut à droite.\nMot de passe oublié ou téléphone perdu : seul l''administrateur peut réinitialiser votre accès. Ne communiquez jamais votre mot de passe ni un code reçu.',
   E'1. Open https://onomo-ticketing.vercel.app and sign in with the e-mail address and temporary password given by IT.\n2. Choose a new personal password: this is required at first sign-in.\n3. If two-step verification is requested, install Microsoft Authenticator (or another authenticator app) on your phone, scan the QR code and enter the 6-digit code.\n4. Choose your language (FR, EN or AR) at the top right.\nForgotten password or lost phone: only the administrator can reset your access. Never share your password or a code you received.'),
  ('Guide : créer un ticket', 'Guide: create a ticket',
   E'1. Cliquez sur « Nouveau ticket ».\n2. Écrivez un sujet court et précis (ex. « Imprimante de la réception bloquée »). Des fiches de solution s''affichent sous le sujet : essayez-les, le problème se règle souvent sans ticket.\n3. Décrivez le problème : depuis quand, quel poste ou quel lieu, le message affiché, ce que vous avez déjà essayé.\n4. Choisissez l''hôtel, la catégorie, la priorité et le responsable IT de votre hôtel.\n5. Ajoutez une photo ou une capture d''écran si elle aide.\n6. Cliquez sur « Créer le ticket ».\nPriorité : Urgente seulement si le service aux clients est bloqué (réception, caisses, Wi-Fi de tout un étage…). Ne mettez jamais de mot de passe ni de donnée client dans un ticket.',
   E'1. Click "New ticket".\n2. Write a short, precise subject (e.g. "Reception printer stuck"). Solution articles appear under the subject: try them, the problem is often fixed without a ticket.\n3. Describe the problem: since when, which computer or place, the message shown, what you already tried.\n4. Choose the hotel, the category, the priority and your hotel''s IT contact.\n5. Add a photo or a screenshot if it helps.\n6. Click "Create ticket".\nPriority: Urgent only when guest service is blocked (reception, tills, Wi-Fi of a whole floor…). Never put a password or guest data in a ticket.'),
  ('Guide : suivre mon ticket et répondre', 'Guide: follow my ticket and reply',
   E'1. Ouvrez « Mes tickets » pour voir vos demandes et leur statut : Nouveau, En cours, En attente (l''IT attend une information ou une pièce), Résolu, Fermé.\n2. Ouvrez un ticket pour lire la conversation et répondre à l''IT.\n3. La cloche en haut à droite vous prévient des nouvelles réponses ; vous recevez aussi un e-mail.\n4. Quand le ticket est résolu, donnez une note de 1 à 5 étoiles : elle aide l''équipe IT à s''améliorer.\nSi le problème revient, répondez dans le même ticket plutôt que d''en créer un nouveau.',
   E'1. Open "My tickets" to see your requests and their status: New, In progress, Pending (IT is waiting for information or a part), Resolved, Closed.\n2. Open a ticket to read the conversation and reply to IT.\n3. The bell at the top right tells you about new replies; you also receive an e-mail.\n4. When the ticket is resolved, give a rating from 1 to 5 stars: it helps the IT team improve.\nIf the problem comes back, reply in the same ticket rather than creating a new one.'),
  ('Guide : utiliser l''Assistant IT', 'Guide: use the IT assistant',
   E'1. Ouvrez « Assistant IT » dans le menu.\n2. Cliquez sur une question fréquente, ou décrivez votre problème (vous pouvez le dicter avec le bouton « Dicter »).\n3. Suivez les vérifications proposées et les fiches de la base de connaissances liées.\n4. Répondez « C''est résolu » ou « Toujours bloqué ». Si c''est toujours bloqué, l''assistant prépare un ticket avec le résumé de ce qui a été essayé.\nL''assistant conseille seulement : il ne modifie rien. N''y saisissez jamais de mot de passe ni de donnée client.',
   E'1. Open "IT assistant" in the menu.\n2. Click a frequent question, or describe your problem (you can dictate it with the "Dictate" button).\n3. Follow the suggested checks and the related knowledge base articles.\n4. Answer "It''s solved" or "Still stuck". If it is still stuck, the assistant prepares a ticket with a summary of what was tried.\nThe assistant only advises: it changes nothing. Never type a password or guest data in it.'),
  ('Guide IT : traiter un ticket', 'IT guide: handle a ticket',
   E'1. Les nouveaux tickets de vos hôtels arrivent dans « Tous les tickets » et dans les notifications ; les tickets urgents arrivent aussi dans le canal Teams IT.\n2. Ouvrez le ticket, passez-le « En cours » et vérifiez le responsable.\n3. Répondez au demandeur avec « Réponse au demandeur », ou écrivez une « Note interne IT » visible seulement par l''IT. Les « Réponses types » insèrent un message prêt.\n4. Indiquez l''équipement concerné (bloc « Équipement concerné ») : l''inventaire montrera ce qui tombe souvent en panne.\n5. Passez « En attente » si vous attendez le demandeur ou un fournisseur.\n6. Une fois réglé, écrivez la solution puis passez le ticket « Résolu ».\nRespectez les délais (SLA) : une alerte est envoyée avant et après le dépassement.',
   E'1. New tickets of your hotels arrive in "All tickets" and in the notifications; urgent tickets also arrive in the IT Teams channel.\n2. Open the ticket, set it to "In progress" and check the assignee.\n3. Reply to the requester with "Reply to requester", or write an "IT internal note" seen only by IT. "Canned replies" insert a ready message.\n4. Set the equipment concerned ("Equipment concerned" block): the inventory will show what breaks down often.\n5. Set "Pending" when you wait for the requester or a supplier.\n6. Once fixed, write the solution then set the ticket to "Resolved".\nKeep to the deadlines (SLA): an alert is sent before and after a breach.'),
  ('Guide IT : inventaire et maintenance planifiée', 'IT guide: inventory and planned maintenance',
   E'Inventaire\n1. Menu « Inventaire » : équipements de vos hôtels, filtres par hôtel, domaine, type et statut, garanties à surveiller.\n2. « Importer un fichier Excel » lit le fichier « Inventaire Materiels IT » de l''hôtel ; les équipements déjà présents sont ignorés.\n3. Tenez l''inventaire à jour : nouvel équipement, matériel retiré, équipement en réparation.\nMaintenance planifiée\n1. Menu « Maintenance planifiée » : tâches récurrentes de vos hôtels (sauvegardes, onduleurs, Wi-Fi…).\n2. « Modèles prêts à l''emploi » ajoute en un clic les tâches courantes.\n3. À chaque échéance, un ticket est créé automatiquement à l''ouverture de l''application : traitez-le comme un ticket normal.',
   E'Inventory\n1. "Inventory" menu: equipment of your hotels, filters by hotel, domain, type and status, warranties to watch.\n2. "Import an Excel file" reads the hotel''s "Inventaire Materiels IT" workbook; equipment already recorded is skipped.\n3. Keep the inventory up to date: new equipment, retired items, equipment under repair.\nPlanned maintenance\n1. "Planned maintenance" menu: recurring tasks of your hotels (backups, UPS, Wi-Fi…).\n2. "Ready-made templates" adds the usual tasks in one click.\n3. On each due date, a ticket is created automatically when the app is opened: handle it like any ticket.'),
  ('Guide direction : rapports et satisfaction', 'Management guide: reports and satisfaction',
   E'1. Le tableau de bord montre les tickets ouverts, urgents et en retard de vos hôtels.\n2. Les rapports donnent, par hôtel et par technicien : nombre de tickets, catégories, priorités, taux de résolution et satisfaction des demandeurs (note moyenne sur 5).\n3. Le bouton PDF exporte un rapport pour une réunion.\n4. Les notes basses et les tickets en retard sont les premiers points à suivre avec l''équipe IT.',
   E'1. The dashboard shows the open, urgent and overdue tickets of your hotels.\n2. Reports give, per hotel and per technician: number of tickets, categories, priorities, resolution rate and requester satisfaction (average rating out of 5).\n3. The PDF button exports a report for a meeting.\n4. Low ratings and overdue tickets are the first points to review with the IT team.'),
  ('Guide administrateur : comptes, rôles et accès', 'Administrator guide: accounts, roles and access',
   E'1. Menu « Utilisateurs » : créez un compte avec un mot de passe temporaire, le rôle principal (Demandeur, IT Hotel, IT Regional, Directeur Hôtel, RH Régional, Administrateur) et l''hôtel ou les hôtels couverts.\n2. Chaque hôtel doit avoir au moins un technicien IT, sinon ses tickets n''ont personne pour les traiter.\n3. Mot de passe oublié ou téléphone de double authentification perdu : modifiez le compte et définissez un nouveau mot de passe temporaire. Il n''y a pas de réinitialisation en libre-service.\n4. Menu « Erreurs » : erreurs rencontrées dans les navigateurs des utilisateurs, à surveiller après chaque mise à jour.',
   E'1. "Users" menu: create an account with a temporary password, the main role (Requester, IT Hotel, IT Regional, Hotel Director, Regional HR, Administrator) and the hotel or hotels covered.\n2. Every hotel needs at least one IT technician, otherwise its tickets have nobody to handle them.\n3. Forgotten password or lost two-step verification phone: edit the account and set a new temporary password. There is no self-service reset.\n4. "Errors" menu: errors met in users'' browsers, to watch after each update.')
) as v(title, title_en, body, body_en)
where not exists (select 1 from public.kb_articles k where k.title = v.title);

commit;
